// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address k) public {
        vm.assume(k != address(0));
        // The contract owner is address(0) (never set); only it can call setApprovedLogger.
        vm.prank(address(0));
        c.setApprovedLogger(k, true);
        assertTrue(c.approvedLoggers(k), "approved logger must be set to true");
    }
}
